#!/bin/sh
# Regenerates src/kinds.rs from Gadgetbridge's ActivityKind enum:
#
#   ./kinds.sh /path/to/Gadgetbridge > src/kinds.rs
#
# Check the line range in the header it writes against the new source.
set -eu

java="$1/app/src/main/java/nodomain/freeyourgadget/gadgetbridge/model/ActivityKind.java"

cat <<'EOF'
//! Gadgetbridge's `ActivityKind` enum: each constant's name (what
//! `ActivityKind.valueOf` takes) and code (what's stored as a sample's raw
//! kind), in declaration order.
//!
//! Generated by `kinds.sh` from `model/ActivityKind.java:28-352` at the
//! pinned commit (see the crate docs); don't edit by hand.

/// `ActivityKind.UNKNOWN.getCode()`.
pub const UNKNOWN: i32 = 0;
/// `ActivityKind.ACTIVITY.getCode()`.
pub const ACTIVITY: i32 = 1;

#[rustfmt::skip]
pub const KINDS: &[(&str, i32)] = &[
EOF
sed -n 's/^    \([A-Z][A-Z_0-9]*\)(\(-\{0,1\}[0-9x|A-Fa-f ]*\),.*/    ("\1", \2),/p' "$java"
echo "];"
